const items = $input.all().map(i => i.json);
const counts = {};
for (const r of items) {
  for (const tag of (r.painSignals || [])) counts[tag] = (counts[tag] || 0) + 1;
}
const topComplaints = items.slice(0, 10).map(r => r.agentSummary).join('\n');
return [{ json: { totalNegativeReviews: items.length, painSignalCounts: counts, topComplaints } }];
